const data = $input.first().json;
const today = data.today || new Date().toISOString().split('T')[0];
const tasks = data.tasks || { total_today: 0, completed_today: 0, overdue_count: 0, items: [] };
const habits = data.habits || { total_habits: 0, completed_today: 0, items: [] };
const goals = data.goals || [];

let digest = `🌅 **Good Morning! Here is your Daily-Productive Briefing for ${today}**\n\n`;

digest += `📋 **Today's Tasks (${tasks.total_today} total, ${tasks.overdue_count} overdue)**:\n`;
if (tasks.items && tasks.items.length > 0) {
  tasks.items.slice(0, 5).forEach(t => {
    const status = t.is_completed ? '✅' : (t.is_overdue ? '⚠️ OVERDUE' : '⏳');
    digest += `- ${status} ${t.title} [${t.priority_level.toUpperCase()}]\n`;
  });
} else {
  digest += `  - No pending tasks due today. Great job!\n`;
}

digest += `\n🔥 **Active Habit Streaks (${habits.completed_today}/${habits.total_habits} done)**:\n`;
if (habits.items && habits.items.length > 0) {
  habits.items.forEach(h => {
    const mark = h.completed_today ? '✅' : '⚪';
    digest += `- ${mark} ${h.name}: ${h.current_streak} day streak (Best: ${h.longest_streak})\n`;
  });
} else {
  digest += `  - No active habits configured.\n`;
}

digest += `\n🎯 **Active Goals Progress**:\n`;
if (goals && goals.length > 0) {
  goals.forEach(g => {
    digest += `- 🎯 **${g.title}**: ${g.progress_percentage}% complete (${g.completed_tasks}/${g.total_tasks} tasks)\n`;
  });
} else {
  digest += `  - No active goals linked.\n`;
}

digest += `\n📈 **7-Day Task Completion Rate**: ${data.weekly_completion_rate}%\n`;
digest += `\n*Have a focused, productive day!*`;

return [{
  json: {
    date: today,
    digest_markdown: digest,
    tasks_count: tasks.total_today,
    habits_count: habits.total_habits
  }
}];
